/**
 * Builds src/data/tracks.js (simple SVG outlines of each circuit).
 *
 * Source: github.com/bacinger/f1-circuits (GeoJSON centre lines, derived from OpenStreetMap).
 * Run once with `npm run tracks`, then commit the generated file.
 *
 *   npm run tracks                 downloads the GeoJSON files, then converts them
 *   TRACKS_DIR=./some/folder npm run tracks    converts local .geojson files instead (offline)
 */
import { readFile, writeFile } from 'node:fs/promises';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';

/** Race round -> file name in the source repo (without .geojson). */
const CIRCUITS = {
  17: 'sg-2008', // Marina Bay: check the repo for a newer layout file if the shape looks outdated
  18: 'us-2012', // Circuit of the Americas
  19: 'mx-1962', // Autodromo Hermanos Rodriguez
  20: 'br-1940', // Interlagos
  21: 'us-2023', // Las Vegas Strip
  22: 'qa-2004', // Lusail
  23: 'ae-2009', // Yas Marina
};

const BASE_URL = 'https://raw.githubusercontent.com/bacinger/f1-circuits/master/circuits/';
const OUT = fileURLToPath(new URL('../src/data/tracks.js', import.meta.url));
const SIZE = 100; // longest side of every outline, in SVG units
const PAD = 6;
const TOLERANCE = 0.35; // simplification, in SVG units

async function loadGeoJson(code) {
  const dir = process.env.TRACKS_DIR;
  if (dir) return JSON.parse(await readFile(join(dir, `${code}.geojson`), 'utf8'));
  const res = await fetch(`${BASE_URL}${code}.geojson`);
  if (!res.ok) throw new Error(`${code}: HTTP ${res.status}`);
  return res.json();
}

function coordinatesOf(geojson) {
  const geometry = geojson.features?.[0]?.geometry ?? geojson.geometry;
  if (geometry.type === 'LineString') return geometry.coordinates;
  if (geometry.type === 'MultiLineString') return geometry.coordinates.flat();
  throw new Error(`unsupported geometry ${geometry.type}`);
}

function perpendicularDistance(p, a, b) {
  const dx = b[0] - a[0];
  const dy = b[1] - a[1];
  const len = Math.hypot(dx, dy);
  if (len === 0) return Math.hypot(p[0] - a[0], p[1] - a[1]);
  return Math.abs(dy * p[0] - dx * p[1] + b[0] * a[1] - b[1] * a[0]) / len;
}

/** Douglas-Peucker line simplification. */
function simplify(points, tolerance) {
  if (points.length < 3) return points;
  let maxDist = 0;
  let index = 0;
  for (let i = 1; i < points.length - 1; i += 1) {
    const d = perpendicularDistance(points[i], points[0], points[points.length - 1]);
    if (d > maxDist) { maxDist = d; index = i; }
  }
  if (maxDist <= tolerance) return [points[0], points[points.length - 1]];
  const left = simplify(points.slice(0, index + 1), tolerance);
  const right = simplify(points.slice(index), tolerance);
  return [...left.slice(0, -1), ...right];
}

function toOutline(coords) {
  const lat0 = coords.reduce((s, c) => s + c[1], 0) / coords.length;
  const k = Math.cos((lat0 * Math.PI) / 180);
  const raw = coords.map(([lon, lat]) => [lon * k, -lat]); // north is up
  const xs = raw.map((p) => p[0]);
  const ys = raw.map((p) => p[1]);
  const minX = Math.min(...xs);
  const minY = Math.min(...ys);
  const scale = SIZE / Math.max(Math.max(...xs) - minX, Math.max(...ys) - minY);
  const pts = raw.map(([x, y]) => [(x - minX) * scale + PAD, (y - minY) * scale + PAD]);
  const slim = simplify(pts, TOLERANCE);
  const w = Math.max(...slim.map((p) => p[0])) + PAD;
  const h = Math.max(...slim.map((p) => p[1])) + PAD;
  const r = (n) => Math.round(n * 10) / 10;
  return {
    viewBox: `0 0 ${r(w)} ${r(h)}`,
    start: [r(slim[0][0]), r(slim[0][1])],
    d: `M${slim.map((p) => `${r(p[0])} ${r(p[1])}`).join('L')}Z`,
  };
}

const tracks = {};
for (const [round, code] of Object.entries(CIRCUITS)) {
  tracks[round] = toOutline(coordinatesOf(await loadGeoJson(code)));
  console.log(`round ${round} (${code}): ${tracks[round].d.split('L').length} points`);
}

const body = `/**
 * Circuit outlines as SVG paths, keyed by race round. Generated by scripts/make-tracks.mjs:
 * do not edit by hand. Re-run \`npm run tracks\` if the calendar changes.
 * Source: bacinger/f1-circuits (derived from OpenStreetMap contributors, ODbL).
 */
export const TRACKS = ${JSON.stringify(tracks, null, 2)};
`;
await writeFile(OUT, body);
console.log(`wrote ${OUT}`);
